// Generate an arbitrary label id (hnswlib::labeltype is size_t)
hnswlib::labeltype id = (hnswlib::labeltype)(*FUZZ_PARAM(size_t));

// Call the functor. The default implementation always returns true, but
// derived implementations may filter by id. We do not assert on the return
// value because both true/false are valid outcomes.
bool allowed = (*functor)(id);

// Record last decision for potential downstream checks (optional metadata)
FUZZ_SET_ATTR_INT(functor, "last_decision", allowed ? 1 : 0);
FUZZ_SET_ATTR_INT(functor, "last_label", (int)(id & 0x7fffffff));

// Validation: functor is kept alive and returned as an output; no ownership transfer occurs.
// The id is in-range for size_t and requires no additional constraints.

// Destroy via base pointer to exercise the virtual destructor and ensure proper cleanup
// of potential derived functors.
delete functor;

// Validation: object is not returned as an output to avoid use-after-free; no further action required.

// Construct a BaseFilterFunctor instance. We sometimes return the base default
// (always-allow) implementation, and sometimes a derived implementation to
// increase behavioral diversity and downstream coverage.

// Randomly choose construction mode: 0=base, 1=mod-filter, 2=range-filter
unsigned int mode = (*FUZZ_PARAM(unsigned int)) % 3;

// Local derived implementations to exercise virtual dispatch paths.
struct ModFilter : public hnswlib::BaseFilterFunctor {
    hnswlib::labeltype mod;
    hnswlib::labeltype rem;
    explicit ModFilter(hnswlib::labeltype m, hnswlib::labeltype r) : mod(m ? m : 1), rem((m ? r % m : 0)) {}
    bool operator()(hnswlib::labeltype id) override {
        // Allow unless id % mod equals rem
        return (id % mod) != rem;
    }
};

struct RangeFilter : public hnswlib::BaseFilterFunctor {
    hnswlib::labeltype lo;
    hnswlib::labeltype hi;
    bool invert;
    RangeFilter(hnswlib::labeltype a, hnswlib::labeltype b, bool inv) : lo(a), hi(b), invert(inv) {}
    bool operator()(hnswlib::labeltype id) override {
        bool in = (id >= lo) && (id <= hi);
        return invert ? !in : in;
    }
};

hnswlib::BaseFilterFunctor *functor = nullptr;

if (mode == 0) {
    // Base functor: default operator() returns true for all ids
    functor = new hnswlib::BaseFilterFunctor();
    FUZZ_SET_ATTR_INT(functor, "is_custom", 0);
} else if (mode == 1) {
    // ModFilter parameters; ensure mod != 0 to avoid UB
    hnswlib::labeltype mod = (hnswlib::labeltype)(*FUZZ_PARAM(size_t));
    if (mod == 0) mod = 1; // enforce valid modulus
    hnswlib::labeltype rem = (hnswlib::labeltype)(*FUZZ_PARAM(size_t));
    functor = new ModFilter(mod, rem);
    FUZZ_SET_ATTR_INT(functor, "is_custom", 1);
    FUZZ_SET_ATTR_INT(functor, "mode", 1);
    FUZZ_SET_ATTR_INT(functor, "mod", (int)(mod & 0x7fffffff));
    FUZZ_SET_ATTR_INT(functor, "rem", (int)(rem & 0x7fffffff));
} else {
    // RangeFilter parameters; normalize order so lo <= hi
    hnswlib::labeltype a = (hnswlib::labeltype)(*FUZZ_PARAM(size_t));
    hnswlib::labeltype b = (hnswlib::labeltype)(*FUZZ_PARAM(size_t));
    bool invert = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
    hnswlib::labeltype lo = a <= b ? a : b;
    hnswlib::labeltype hi = a <= b ? b : a;
    functor = new RangeFilter(lo, hi, invert);
    FUZZ_SET_ATTR_INT(functor, "is_custom", 1);
    FUZZ_SET_ATTR_INT(functor, "mode", 2);
    FUZZ_SET_ATTR_INT(functor, "lo", (int)(lo & 0x7fffffff));
    FUZZ_SET_ATTR_INT(functor, "hi", (int)(hi & 0x7fffffff));
    FUZZ_SET_ATTR_INT(functor, "invert", invert ? 1 : 0);
}

// Property: functor must be non-null for the fuzzer runtime to own and reuse.
FUZZ_ASSERT(functor != nullptr, "Allocation of BaseFilterFunctor failed");

// Optional smoke call to record behavior metadata; valid for any implementation.
hnswlib::labeltype probe = (hnswlib::labeltype)(*FUZZ_PARAM(size_t));
bool allowed_probe = (*functor)(probe);
FUZZ_SET_ATTR_INT(functor, "last_decision", allowed_probe ? 1 : 0);
FUZZ_SET_ATTR_INT(functor, "last_label", (int)(probe & 0x7fffffff));

// Validation: We ensure constructed object is valid, set attributes to guide
// downstream stubs, and do not delete it. The runtime will take ownership.
